// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2023, "4-5", [{"author":"О. Подлесская","question":"Вот такой знак на стекле машины означает «__________».","choices":["ученик за рулём","украденная машина","учитель за рулём","усталый водитель","усатый водитель."],"key":"А","review":["Знак на машине","В треугольнике изображена буква У. Такую букву ставят на учебные машины, на которых учатся водить.","За рулём учебной машины — ученик, а инструктор сидит рядом. Значит, знак предупреждает, что за рулём ученик."],"figure":{"condition":{"src":"assets/medvezhonok/2023/4-5-1.webp","width":170,"height":153,"pixelWidth":170,"pixelHeight":153,"alt":"Белый треугольник с красной каймой и чёрной буквой У."}}},{"author":"Е. Муравенко","question":"Какую букву нельзя вставить вместо прочерка в запись <em>б_к</em>, чтобы получилось слово?","choices":["<em>а</em>","<em>о</em>","<em>и</em>","<em>ы</em>","<em>у</em>."],"key":"В","review":["Буква между Б и К","Подставь четыре гласные: «бак» — ёмкость, «бок» — сторона, «бык» — животное, «бук» — дерево.","После подстановки И выходит «бик». Такого нарицательного русского слова нет, поэтому нельзя вставить И."]},{"author":"И. Рубанов","question":"Какую букву при наборе на компьютере иногда используют вместо знака умножения?","choices":["<em>жэ</em>","<em>ка</em>","<em>эм</em>","<em>эф</em>","<em>ха</em>."],"key":"Д","review":["Знак умножения на клавиатуре","Посмотри на знак ×: две наклонные линии пересекаются посередине. В кириллице одна буква устроена так же.","Это Х, её называют «ха». В компьютерной записи похожая буква иногда заменяет ×."]},{"author":"А. Ковалёва","question":"Незнайка подбирал рифму к своему имени. Знайка посмотрел на получившиеся рифмы, показал на одно слово и сказал: «Такого слова не бывает!» Какое слово он имел в виду?","choices":["<em>знайка</em>","<em>всезнайка</em>","<em>всенезнайка</em>","<em>зазнайка</em>","<em>угадайка</em>."],"key":"В","review":["Рифмы Незнайки","Подбери значения четырём вариантам: знайка много знает, всезнайка считает, что знает всё, зазнайка зазнаётся, а угадайкой могут назвать игру на угадывание.","«Всенезнайка» подходит по звучанию, но это придуманное для рифмы слово. Обычное слово для того, кто мало знает, — «незнайка»."]},{"author":"Б. Иомдин","question":"Того, кто часто смеётся, называют _____.","choices":["<em>смешинка</em>","<em>смешок</em>","<em>смельчак</em>","<em>весельчак</em>","<em>посмешище</em>."],"key":"Г","review":["Любитель посмеяться","Ищи название человека, а не звука или повода для смеха. «Смешок» — звук, «смешинка» связана с желанием смеяться, а «посмешище» — тот, над кем смеются.","Смельчака называют так за храбрость. Того, кто веселится и часто смеётся, называют весельчаком."]},{"author":"Е. Муравенко","question":"В каком предложении слово <em>идёт</em> употреблено в прямом, а не в переносном значении?","choices":["<em>Идёт концерт.</em>","<em>Идёт дождь.</em>","<em>Идёт поезд.</em>","<em>Идёт время.</em>","<em>Идёт школьник.</em>"],"key":"Д","review":["Как употреблено слово «идёт»","В прямом значении «идёт» означает, что кто-то передвигается шагами. Попробуй заменить глагол словом «шагает».","Школьник может шагать. В других вариантах «идёт» означает «происходит», «движется», «падает» или «проходит»."]},{"author":"А. Ковалёва","question":"Детям дали попробовать неизвестный им фрукт и попросили сказать, какой он на вкус. Они дали 5 разных ответов. Какой ответ правильный?","choices":["длинный","твёрдый","красный","сладкий","ароматный."],"key":"Г","review":["Какой фрукт на вкус","Отдели показания чувств. Форму и цвет можно увидеть, твёрдость — почувствовать при нажатии, а аромат — уловить носом.","Сладость относится ко вкусу. Поэтому правильный ответ на вопрос «какой на вкус?» — «сладкий»."]},{"author":"О. Подлесская","question":"Что может быть чёрным, красным, молотым, жгучим?","choices":["черешня","хлеб","смородина","перец","горошек."],"key":"Г","review":["Четыре признака","Ищи продукт, к которому подходят сразу все признаки. «Молотый» подсказывает пряность, а «жгучий» — острый вкус.","Перец бывает чёрным и красным, а ещё молотым и жгучим. Для остальных продуктов все четыре признака сразу не подходят."]},{"author":"Л. Фёдорова","question":"В какой паре слова различаются по роду?","choices":["<em>горох — горошек</em>","<em>морковь — морковка</em>","<em>редис — редиска</em>","<em>репа — репка</em>","<em>лук — лучок</em>."],"key":"В","review":["Род названий овощей","Подставь «мой» или «моя» к каждому слову. «Горох — горошек» и «лук — лучок» мужского рода, «морковь — морковка» и «репа — репка» женского.","Говорят «мой редис» и «моя редиска». Только в этой паре род меняется."]},{"author":"И. Рубанов","question":"У заглавных букв А и С — по два конца, у буквы Б — один конец, а у буквы О концов нет. А какое наибольшее число концов может быть у заглавной русской буквы?","choices":["2","3","4","5","6."],"key":"Д","review":["Концы заглавных букв","Отмечай свободные концы линий. Например, у Х четыре таких конца, а линия внутри А соединяет две стороны и новых концов не даёт.","В Ж три линии расходятся от середины в шести направлениях: вверх, вниз и по четырём диагоналям. У остальных букв свободных концов меньше, максимум — шесть."]},{"author":"А. Сомин","question":"Что означает слово <em>tum-tum</em> на чинукском жаргоне (одном из языков североамериканских индейцев)?","choices":["желудок","лёгкие","сердце","печень","почки."],"key":"В","review":["Слово на чинукском","Прочитай tum-tum вслух и прислушайся: два коротких одинаковых звука напоминают ритмичный стук.","Из перечисленных органов так стучит сердце. В чинукском жаргоне tum-tum действительно означает «сердце»."]},{"author":"А. Пиперски","question":"Герой одного фильма делает отжимания и считает: «…восемь, девять, _____, один, два, три…». Заполните пропуск.","choices":["пятнадцать","двадцать пять","тридцать шесть","сорок","сорок пять."],"key":"Г","review":["Счёт при отжиманиях","«Восемь, девять» заканчивают один десяток, а «один, два, три» — это уже окончания чисел следующего десятка.","Между ними нужно назвать круглое число. Из вариантов подходит «сорок»: дальше идут сорок один, сорок два и сорок три."]},{"author":"Т. Амбарцумова","question":"Одна девочка побывала в зоопарке и увидела там симпатичную обезьяну. Теперь она в шутку говорит, что считает эту обезьяну своей собственной. Какой породы была обезьяна?","choices":["игрунка","тамарин","мандрил","гамадрил","мартышка."],"key":"Б","review":["Чья обезьяна","Проверь, какое название можно услышать как ответ на вопрос «чей?». Например, про предмет, принадлежащий Тамаре, говорят «Тамарин».","Название обезьяны «тамарин» звучит так же. Девочка может шутливо принять название животного за указание на хозяйку."]},{"author":"А. Ковалёва","question":"В предложениях на стыке слов могут быть «спрятаны» новые слова, например, в предложении <em>В огоро<strong>де ло</strong>пата — основной помощник</em> «спрятано» слово <em>дело</em>. Ниже в четырёх предложениях спрятаны названия овощей, а в одном — название фрукта. В каком?","choices":["<em>Во дворе папа посадил дерево.</em>","<em>Доктор сделал укол больному.</em>","<em>Мы вчера отнесли варенье бабушке.</em>","<em>Ты квас любишь?</em>","<em>Впереди с капитаном шагал его помощник</em>."],"key":"В","review":["Овощи и фрукт на стыке","Ищи конец одного слова и начало другого. В «двоРЕ ПАпа» есть репа, в «сделаЛ УКол» — лук, в «ТЫ КВАс» — тыква, во «впеРЕДИ С» — редис.","В «отнеСЛИ ВАренье» спрятана слива. Это единственный фрукт, значит, нужная фраза про варенье."]},{"author":"Л. Фёдорова","question":"<em>— Мигом за ребятами! Одна _____ здесь, другая там!</em> (Василий Аксёнов) Какое слово здесь пропущено?","choices":["<em>голова</em>","<em>рука</em>","<em>лапа</em>","<em>подошва</em>","<em>нога</em>."],"key":"Д","review":["Мигом за ребятами","Слово «мигом» подсказывает, что герой должен поторопиться. «Одна здесь, другая там» рисует широкий и быстрый шаг.","В известном выражении говорят «одна нога здесь, другая там». Им просят быстро сходить куда-нибудь и вернуться."]},{"author":"О. Подлесская","question":"В какой паре слова могут называть похожие предметы?","choices":["<em>решето — лукошко</em>","<em>лукошко — коромысло</em>","<em>сито — корыто</em>","<em>коромысло — корыто</em>","<em>решето — сито</em>."],"key":"Д","review":["Похожие предметы","Представь назначение предметов: в лукошке несут собранное, коромыслом носят вёдра, корыто служит ёмкостью.","Решето и сито устроены похоже: у обоих есть отверстия, через которые что-то просеивают. Эти слова называют похожие предметы."]},{"author":"О. Подлесская","question":"Какое прилагательное сильно отличается по смыслу от остальных четырёх?","choices":["<em>горный</em>","<em>лесной</em>","<em>степенный</em>","<em>равнинный</em>","<em>таёжный</em>."],"key":"В","review":["Прилагательные о местности","Свяжи слова с тем, что они описывают. Горный, лесной, равнинный и таёжный могут указывать на горы, лес, равнину или тайгу.","«Степенный» означает спокойный, важный и неторопливый. Для степи есть другое слово — «степной»."]},{"author":"И. Рубанов","question":"Посуда для сливочного масла называется _____.","choices":["<em>масленица</em>","<em>маслёнка</em>","<em>маслёнок</em>","<em>маслина</em>","<em>маслохранительница</em>."],"key":"Б","review":["Посуда для масла","Различи похожие слова. Масленица — праздник, маслёнок — гриб, маслина — плод оливкового дерева.","Сливочное масло хранят в маслёнке. Так и называется небольшая посуда с крышкой, которую ставят на стол."]},{"author":"А. Ковалёва","question":"Какое слово построено не по тому принципу, что остальные?","choices":["<em>пароход</em>","<em>тепловоз</em>","<em>теплоход</em>","<em>электровоз</em>","<em>мусоровоз</em>."],"key":"Д","review":["Названия транспорта","Первая часть слов «пароход», «тепловоз», «теплоход» и «электровоз» намекает, откуда берётся сила для движения: от пара, двигателя, работающего на топливе, или электричества.","В «мусоровозе» первая часть называет груз, который машина возит. Мусор везут, и он не приводит машину в движение."]},{"author":"Б. Иомдин","question":"На афише в Польше написано название фильма: Chłopak spotyka dziewczynę («Мальчик встречает девочку»). Как по-польски «встречать»?","choices":["wstreczać","vstrechać","spotykać","chłopać","dziewczyć."],"key":"В","review":["Глагол на польской афише","Сопоставь части названия: Chłopak — мальчик, dziewczynę — девочку. Посередине остаётся spotyka со значением «встречает».","Чтобы получить польское «встречать», ищи начальную форму того же глагола. Она оканчивается на ć: spotykać."]},{"author":"Л. Фёдорова","question":"Когда ребята ходили в детский сад, их называли Антон, Коля, Саша, Федя, Лёша. Когда они пошли записываться в первый класс, учительница записала по алфавиту их полные имена. Чьё имя оказалось первым в алфавитном списке?","choices":["Антона","Лёши","Коли","Саши","Феди."],"key":"Г","review":["Полные имена по алфавиту","Восстанови полные имена: Антон, Николай, Александр, Фёдор, Алексей. Среди имён на А сравни вторые буквы: Л раньше Н.","«Александр» и «Алексей» начинаются одинаково, на «Алекс». Затем идут А и Е, А раньше. Значит, первым оказалось имя Саши."]},{"author":"А. Ковалёва","question":"Кем был отец героя русских былин Алёши Поповича?","choices":["царём","священником","военным","рыбаком","космонавтом."],"key":"Б","review":["Отец Алёши Поповича","Разбери имя «Алёша Попович». В былинах часть «-ович» указывает, чей это сын.","В «Поповиче» слышно старинное слово «поп», то есть священник. Значит, Алёша — сын священника."]},{"author":"Л. Фёдорова","question":"В стихотворении Михаила Яснова «Чудетство»\n<em>«…по дальним дорогам\nБредут Носомот с Бегерогом».</em>\nЧто нужно сделать с именами Носомот и Бегерог, чтобы получились названия зверей?","choices":["поменять друг с другом первые слоги","поменять друг с другом вторые слоги","поменять друг с другом третьи слоги","зачеркнуть по четыре буквы в каждом имени","ничего не надо делать, есть такие звери."],"key":"В","review":["Носомот и Бегерог","Раздели имена на слоги: «но-со-мот» и «бе-ге-рог». Начала напоминают названия зверей: «носо-» и «беге-».","Поменяй местами «мот» и «рог». Получатся носорог и бегемот, значит, нужно поменять третьи слоги."]},{"author":"А. Сомин","question":"Подумайте о том, какие значения выражаются разными падежами, и догадайтесь, название какого русского падежа переводится на латынь как instrumentalis?","choices":["родительного","дательного","винительного","творительного","предложного."],"key":"Г","review":["Падеж для инструмента","Латинское instrumentalis напоминает слово «инструмент». Спроси, чем мы пишем, режем или забиваем гвоздь.","На вопрос «чем?» отвечают «ручкой», «ножом», «молотком». Эти формы стоят в творительном падеже."]},{"author":"О. Подлесская","question":"Какое слово пропущено в стихотворении Владимира Орлова «Ворона»?\n<em>— Кра! — Кричит ворона. — Кража!\nКараул! Грабёж! Пропажа!\nВор прокрался утром рано!\nГрош украл он из кармана!\nКарандаш! _____! Пробку!\nИ красивую коробку!</em>","choices":["<em>Линейку</em>","<em>Записку</em>","<em>Конфетку</em>","<em>Картонку</em>","<em>Колечко</em>."],"key":"Г","review":["Вороний перечень вещей","Прислушайся к вороньему «кра» и к словам «кража», «кармана», «карандаш». В них повторяются близкие звуки «кра» и «кар».","Из вариантов только «картонку» начинается на «кар». Это слово продолжает звуковую игру и называет ещё одну пропавшую вещь."]},{"author":"Б. Иомдин","question":"Как по-фински называется животное с длинной шеей?","choices":["jaguaari","kirahvi","krokotiili","leijona","tiikeri."],"key":"Б","review":["Зверь с длинной шеей","Слова jaguaari, krokotiili и tiikeri похожи на «ягуар», «крокодил» и «тигр». В leijona можно узнать сходство с английским lion — «лев».","Животное с длинной шеей — жираф. Ему соответствует оставшееся финское слово kirahvi."]},{"author":"Т. Амбарцумова","question":"<em>Услышать можно <strong>это</strong> среди толпы людской,\nУвидеть отраженье — в столярной мастерской.</em>\nКакое слово заменено словом <strong>это</strong>?","choices":["<em>возглас</em>","<em>голос</em>","<em>ропот</em>","<em>топот</em>","<em>шёпот</em>."],"key":"В","review":["Зеркало в мастерской","«Отраженье» подсказывает, что слово надо прочитать справа налево. Ищи среди результатов название столярного инструмента.","«Ропот» превращается в «топор». Ропот можно услышать в толпе, а топор увидеть в мастерской."]},{"author":"И. Иткин","question":"Корней Чуковский иногда обращался к своей маленькой дочери Лиде с ласковым двустишием:\n<em>Лидочек,\n__________.</em>\nПо воспоминаниям Лидии Корнеевны, слыша это двустишие, она удивлялась: «Разве я на чём-нибудь езжу?». Как выглядит вторая строка двустишия?","choices":["<em>Нет прекрасней дочек</em>","<em>Лучшая из дочек</em>","<em>Солнечный звоночек</em>","<em>Доченька-цветочек</em>","<em>Милый мой цветочек</em>."],"key":"Б","review":["Двустишие для Лиды","Прочитай варианты слитно и ищи сочетание, которое могло напомнить словечко от «ездить».","В «Лучшая из дочек» Лиде послышалось «ездочек». Поэтому она и спрашивала, ездит ли на чём-нибудь."]},{"author":"Е. Муравенко","question":"Сколько раз в этих строчках Агнии Барто встречается звук [д]?\n<em>И вдруг я вижу —\nВходит дед.\nОн с бородой,\nВ тулуп одет,\nТулуп до самых пят!</em>","choices":["три","четыре","пять","шесть","семь."],"key":"А","review":["Твёрдый звук в стихах","Произнеси слова с буквой Д. В «входит», в начале «дед» и в «одет» звучит мягкий [д’], а в конце «дед» слышится глухой [т].","Твёрдый [д] слышен во «вдруг», «бородой» и «до». Всего три раза."]},{"author":"П. Долгополов","question":"В «Толковом словаре живого великорусского языка» В. И. Даля, изданном во второй половине XIX в., можно найти слово <em>ежежды</em>. А что оно означает?","choices":["при условии что","потому что","жадно","уже давно","каждый раз."],"key":"Д","review":["Старинное слово у Даля","Сравни начала «еже-» в словах «ежедневно» и «ежегодно»: речь о каждом дне или каждом годе. Часть «-жды» напоминает «дважды» и «трижды», где считают разы.","Соедини значения и получишь «каждый раз». Так Даль и объясняет слово «ежежды»."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
